        for r in [0,H-1]:
            if not vis[r][c]: vis[r][c]=True; q.append((r,c)); seen.add((r,c))
    while q:
        r,c=q.popleft()
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
